const STAGE_ORDER = ['Prospect', 'Meeting Booked', 'Qualified', 'Proposal Sent', 'Decision Pending'];
const all = $input.all().map(i => i.json).filter(r => r && r.name);
const live = all.filter(r => r.stage && !String(r.stage).startsWith('Closed'));

const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
const todayMid = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const staleCutoff = new Date(todayMid.getTime() - 7 * 86400000);
const day = d => d ? String(d).slice(0, 10) : null;

let msg = `📊 Sales Pipeline — ${todayMid.toISOString().slice(0, 10)}\n`;

if (!live.length) {
  msg += '\nPipeline is empty. Add prospects to the "pipeline" data table in n8n.';
  return [{ json: { digest: msg } }];
}

for (const stage of STAGE_ORDER) {
  const rows = live.filter(r => r.stage === stage);
  if (!rows.length) continue;
  msg += `\n${stage}:\n`;
  for (const r of rows) {
    const who = r.company ? `${r.name} (${r.company})` : r.name;
    const step = r.next_step ? ` — ${r.next_step}` : '';
    const due = r.next_step_due ? ` (due ${day(r.next_step_due)})` : '';
    msg += `• ${who}${step}${due}\n`;
  }
}

const missing = live.filter(r => !r.next_step);
if (missing.length) {
  msg += '\n⚠ No documented next step:\n';
  for (const r of missing) msg += `• ${r.name} — decide what moves this forward, today\n`;
}

const overdue = live.filter(r => r.next_step_due && new Date(r.next_step_due) < todayMid);
if (overdue.length) {
  msg += '\n🔴 Overdue next steps:\n';
  for (const r of overdue) msg += `• ${r.name} — ${r.next_step || '(none)'} (was due ${day(r.next_step_due)})\n`;
}

const stale = live.filter(r => r.last_touch && new Date(r.last_touch) < staleCutoff);
if (stale.length) {
  msg += '\n🥶 No touch in 7+ days:\n';
  for (const r of stale) msg += `• ${r.name} — last touch ${day(r.last_touch)}\n`;
}

msg += '\n— 30 minutes. Move each prospect one step forward.';
return [{ json: { digest: msg } }];
